import sys
import json
import os

class TaskDB:
    def __init__(self):
        self.tasks = []
        self.next_id = 1
        self.db_path = "tasks.db"

    def add(self, tag, task_text):
        task = {"id": self.next_id, "tag": tag, "task": task_text}
        self.tasks.append(task)
        self.next_id += 1
        return f"added {task['id']}"

    def find(self, field, value):
        matches = [task for task in self.tasks if task[field] == value]
        if not matches:
            return "no matches"
        return "\n".join(f"{task['id']} {task['tag']} {task['task']}" for task in matches)

    def save(self, path):
        with open(path, "w") as f:
            json.dump(self.tasks, f)
        return f"saved {len(self.tasks)}"

    def load(self, path):
        if not os.path.exists(path):
            return "no matches"
        with open(path, "r") as f:
            self.tasks = json.load(f)
            self.next_id = max(task["id"] for task in self.tasks) + 1 if self.tasks else 1
        return f"loaded {len(self.tasks)}"

    def process_command(self, line):
        parts = line.strip().split()
        if not parts:
            return "unknown command"
        cmd = parts[0]
        if cmd == "add":
            if len(parts) < 3:
                return "unknown command"
            return self.add(parts[1], " ".join(parts[2:]))
        elif cmd == "find":
            if len(parts) < 3:
                return "unknown command"
            return self.find(parts[1], " ".join(parts[2:]))
        elif cmd == "save":
            if len(parts) < 2:
                return "unknown command"
            return self.save(parts[1])
        elif cmd == "load":
            if len(parts) < 2:
                return "unknown command"
            return self.load(parts[1])
        elif cmd == "quit":
            return "quit"
        else:
            return "unknown command"

    def run(self):
        db = TaskDB()
        for line in sys.stdin:
            line = line.strip()
            if line:
                result = db.process_command(line)
                if result == "quit":
                    break
                print(result)

