import json
import os

class TaskDB:
    def __init__(self):
        self.tasks = []
        self.next_id = 1
        self.db_path = "tasks.db"

    def add(self, tag, task):
        task_id = self.next_id
        self.tasks.append({"id": task_id, "tag": tag, "task": task})
        self.next_id += 1
        print(f"added {task_id}")

    def find(self, field, value):
        matches = [task for task in self.tasks if task[field] == value]
        if matches:
            for task in matches:
                print(f"{task['id']} {task['tag']} {task['task']}")
        else:
            print("no matches")

    def save(self, path):
        with open(path, "w") as f:
            json.dump(self.tasks, f)
        print(f"saved {len(self.tasks)}")

    def load(self, path):
        if not os.path.exists(path):
            print("no matches")
