        with open(path, "r") as f:
            self.tasks = json.load(f)
            self.next_id = max(task["id"] + 1 for task in self.tasks) if self.tasks else 1
        print(f"loaded {len(self.tasks)}")

    def process_command(self, line):
        line = line.strip()
        if not line:
            return
        parts = line.split()
        if not parts:
            return
        cmd = parts[0]
        if cmd == "add":
            if len(parts) < 3:
                print("unknown command")
                return
            self.add(parts[1], " ".join(parts[2:]))
        elif cmd == "find":
            if len(parts) < 3:
                print("unknown command")
                return
            field = parts[1]
            value = " ".join(parts[2:])
            if field not in ["task", "tag"]:
                print("unknown command")
                return
            self.find(field, value)
        elif cmd == "save":
            if len(parts) < 2:
                print("unknown command")
                return
            self.save(" ".join(parts[1:]))
